<template>
  <b-form class="filter mb-4" @submit.stop.prevent="onSubmit" @reset="onReset">
    <b-card no-body :title="title">
      <b-card-body>
        <Loading v-if="!loaded" fill />

        <b-card-title v-if="title" :title="title" />

        <!-- Natural Language Search -->
        <b-form-group v-if="canSupportNaturalLanguage" class="natural-language-search" :label="$t('search.naturalLanguageQuery')" :label-for="ids.naturalLanguage" :description="naturalLanguageDescription">
          <div class="alert alert-info mb-3">
            {{ $t('search.naturalLanguageInfo') }}
          </div>
          <b-alert v-if="naturalLanguageError" variant="danger" show dismissible @dismissed="naturalLanguageError = null">
            {{ naturalLanguageError }}
          </b-alert>
          <div>
            <b-form-input
              :id="ids.naturalLanguage"
              v-model="naturalLanguageQuery"
              type="text"
              :placeholder="$t('search.enterNaturalLanguageQuery')"
              @keyup.enter="directNaturalLanguageSearch"
              @keydown.enter.prevent
              class="mb-3"
            />
            <div class="d-flex justify-content-end">
              <b-button variant="outline-secondary" @click="applyNaturalLanguageQuery" :disabled="naturalLanguageLoading && naturalLanguageAction !== 'populate'" class="mr-2">
                <span v-if="naturalLanguageLoading && naturalLanguageAction === 'populate'">
                  {{ $t('search.processing') }}
                </span>
                <span v-else>
                  {{ $t('search.populateForm') }}
                </span>
              </b-button>
              <b-button variant="primary" @click="directNaturalLanguageSearch" :disabled="naturalLanguageLoading && naturalLanguageAction !== 'search'">
                <span v-if="naturalLanguageLoading && naturalLanguageAction === 'search'">
                  {{ $t('search.processing') }}
                </span>
                <span v-else>
                  {{ $t('search.searchDirectly') }}
                </span>
              </b-button>
            </div>
          </div>
        </b-form-group>

        <hr v-if="canSupportNaturalLanguage">

        <b-form-group v-if="canFilterFreeText" class="filter-freetext" :label="$t('search.freeText')" :label-for="ids.q" :description="$t('search.freeTextDescription')">
          <multiselect
            :id="ids.q" :value="query.q" @input="setSearchTerms"
            multiple taggable :options="query.ids"
            :placeholder="$t('search.enterSearchTerms')"
            :tagPlaceholder="$t('search.addSearchTerm')"
            :noOptions="$t('search.addSearchTerm')"
            @tag="addSearchTerm"
          >
            <template #noOptions>{{ $t('search.noOptions') }}</template>
          </multiselect>
        </b-form-group>

        <b-form-group v-if="canFilterExtents" class="filter-datetime" :label="$t('search.temporalExtent')" :label-for="ids.datetime" :description="$t('search.dateDescription')">
          <date-picker
            range type="datetime" v-model="datetime" input-class="form-control mx-input"
            :id="ids.datetime" :lang="datepickerLang" :format="dateTimeFormat"
          />
        </b-form-group>

        <b-form-group v-if="canFilterExtents" class="filter-bbox" :label="$t('search.spatialExtent')" :label-for="ids.bbox">
          <b-form-radio-group :id="ids.bbox" v-model="spatialExtentType" :options="spatialExtentOptions" name="spatialExtent" @change="setBBox()" />
          <Map class="mb-4" v-if="spatialExtentType === 'boundingBox'" :stac="stac" selectBounds @bounds="setBBox" scrollWheelZoom />
        </b-form-group>

        <b-form-group v-if="conformances.CollectionIdFilter" class="filter-collection" :label="$tc('stacCollection', collections.length)" :label-for="ids.collections">
          <multiselect
            v-bind="collectionSelectOptions"
            @input="setCollections"
            @tag="addCollection"
            @search-change="searchCollections"
          >
            <template #noOptions>{{ $t('search.noOptions') }}</template>
            <template v-if="additionalCollectionCount > 0" #afterList>
              <li>
                <strong class="multiselect__option multiselect__option--disabled">
                  {{ $t("multiselect.andMore", {count: additionalCollectionCount}) }}
                </strong>
              </li>
            </template>
          </multiselect>
        </b-form-group>

        <b-form-group v-if="conformances.ItemIdFilter" class="filter-item-id" :label="$t('search.itemIds')" :label-for="ids.ids">
          <multiselect
            :id="ids.ids" :value="query.ids" @input="setIds"
            multiple taggable :options="query.ids"
            :placeholder="$t('search.enterItemIds')"
            :tagPlaceholder="$t('search.addItemIds')"
            :noOptions="$t('search.addItemIds')"
            @tag="addId"
          >
            <template #noOptions>{{ $t('search.noOptions') }}</template>
          </multiselect>
        </b-form-group>

        <b-form-group v-if="showAdditionalFilters" class="additional-filters" :label="$t('search.additionalFilters')">
          <b-form-radio-group v-model="filtersAndOr" :options="andOrOptions" name="logical" size="sm" />

          <b-dropdown size="sm" :text="$t('search.addFilter')" block variant="primary" class="queryables mt-2 mb-3" menu-class="w-100">
            <template v-for="queryable in sortedQueryables">
              <b-dropdown-item v-if="queryable.supported" :key="queryable.id" @click="additionalFieldSelected(queryable)">
                {{ queryable.title }}
                <b-badge variant="dark" class="ml-2">{{ queryable.id }}</b-badge>
              </b-dropdown-item>
            </template>
          </b-dropdown>

          <QueryableInput
            v-for="(filter, index) in filters" :key="filter.id"
            :value.sync="filter.value"
            :operator.sync="filter.operator"
            :queryable="filter.queryable"
            :index="index"
            :cql="cql"
            @remove-queryable="removeQueryable(index)"
          />
        </b-form-group>

        <hr v-if="canFilterExtents || conformances.CollectionIdFilter || conformances.ItemIdFilter || showAdditionalFilters">

        <b-form-group v-if="canSort" class="sort" :label="$t('sort.title')" :label-for="ids.sort" :description="$t('search.notFullySupported')">
          <multiselect
            :id="ids.sort" :value="sortTerm" @input="sortFieldSet"
            :options="sortOptions" track-by="value" label="text"
            :placeholder="$t('default')"
            :selectLabel="$t('multiselect.selectLabel')"
            :selectedLabel="$t('multiselect.selectedLabel')"
            :deselectLabel="$t('multiselect.deselectLabel')"
          />
          <SortButtons v-if="sortTerm && sortTerm.value" class="mt-1" :value="sortOrder" enforce @input="sortDirectionSet" />
        </b-form-group>

        <b-form-group class="limit" :label="$t('search.itemsPerPage')" :label-for="ids.limit" :description="$t('search.itemsPerPageDescription', {maxItems})">
          <b-form-input
            :id="ids.limit" :value="query.limit" @change="setLimit" min="1"
            :max="maxItems" type="number"
            :placeholder="$t('defaultWithValue', {value: itemsPerPage})"
          />
        </b-form-group>
      </b-card-body>
      <b-card-footer>
        <b-button type="submit" variant="primary">{{ $t('submit') }}</b-button>
        <b-button type="reset" variant="danger" class="ml-3">{{ $t('reset') }}</b-button>
      </b-card-footer>
    </b-card>
  </b-form>
</template>

<script>
import { BBadge, BDropdown, BDropdownItem, BForm, BFormGroup, BFormInput, BFormRadioGroup, BButton } from 'bootstrap-vue';
import Multiselect from 'vue-multiselect';
import { mapGetters, mapState } from "vuex";
import refParser from '@apidevtools/json-schema-ref-parser';

import Utils, { schemaMediaType } from '../utils';
import { ogcQueryables } from "../rels";

import ApiCapabilitiesMixin, { TYPES } from './ApiCapabilitiesMixin';
import DatePickerMixin from './DatePickerMixin';
import Loading from './Loading.vue';

import STAC from '../models/stac';
import Cql from '../models/cql2/cql';
import Queryable from '../models/cql2/queryable';
import CqlValue from '../models/cql2/value';
import CqlLogicalOperator from '../models/cql2/operators/logical';
import { stacRequest } from '../store/utils';

function getQueryDefaults() {
  return {
    q: [],
    datetime: null,
    bbox: null,
    intersects: null,
    limit: null,
    ids: [],
    collections: [],
    sortby: null,
    filters: null,
    naturalLanguageQuery: ''
  };
}

function getDefaults() {
  return {
    sortOrder: 1,
    sortTerm: null,
    spatialExtentType: 'none',
    query: getQueryDefaults(),
    filtersAndOr: 'and',
    filters: [],
    selectedCollections: [],
    naturalLanguageQuery: '',
    naturalLanguageExplanation: '',
    naturalLanguageLoading: false,
    naturalLanguageError: null,
    naturalLanguageAction: null,
    naturalSearchArea: null
  };
}

let formId = 0;

export default {
  name: 'SearchFilter',
  components: {
    BBadge,
    BDropdown,
    BDropdownItem,
    BForm,
    BFormGroup,
    BFormInput,
    BFormRadioGroup,
    BButton,
    QueryableInput: () => import('./QueryableInput.vue'),
    Loading,
    Map: () => import('./Map.vue'),
    SortButtons: () => import('./SortButtons.vue'),
    Multiselect
  },
  mixins: [
    ApiCapabilitiesMixin,
    DatePickerMixin
  ],
  props: {
    parent: {
      type: Object,
      required: true
    },
    title: {
      type: String,
      required: true
    },
    type: { // Collections or Global or Items
      type: String,
      required: true
    },
    value: {
      type: Object,
      default: () => ({})
    }
  },
  data() {
    return Object.assign({
      results: null,
      loaded: false,
      queryables: null,
      hasAllCollections: false,
      collections: [],
      collectionsLoadingTimer: null,
      additionalCollectionCount: 0,
      naturalLanguageLoading: false
    }, getDefaults());
  },
  computed: {
    ...mapState(['itemsPerPage', 'maxItemsPerPage', 'uiLanguage']),
    ...mapGetters(['canSearchCollections', 'supportsConformance']),
    canSupportNaturalLanguage() {
      return Boolean(this.$store.state.semanticSearchApiUrl);
    },
    collectionSelectOptions() {
      let taggable = !this.hasAllCollections;
      let isResult = this.collections.length > 0 && !this.hasAllCollections;
      return {
        id: this.ids.collections,
        value: this.selectedCollections,
        multiple: true,
        taggable,
        options: this.collections, // query.collections
        trackBy: "value",
        label: "text",
        placeholder: taggable ? this.$t('search.enterCollections') : this.$t('search.selectCollections'),
        tagPlaceholder: this.$t('search.addCollections'),
        selectLabel: this.$t('multiselect.selectLabel'),
        selectedLabel: this.$t('multiselect.selectedLabel'),
        deselectLabel: this.$t('multiselect.deselectLabel'),
        limitText: count => this.$t("multiselect.andMore", {count}),
        loading: this.collectionsLoadingTimer !== null,
        showNoResults: false,
        internalSearch: !isResult
      };
    },
    collectionSearchLink() {
      return this.parent instanceof STAC && this.parent.getApiCollectionsLink();
    },
    canSearchCollectionsFreeText() {
      return this.canSearchCollections && this.supportsConformance(TYPES.Collections.FreeText);
    },
    ids() {
      let obj = {};
      ['q', 'datetime', 'bbox', 'collections', 'ids', 'sort', 'limit', 'naturalLanguage']
        .forEach(field => obj[field] = field + formId);
      return obj;
    },
    stac() {
      if (this.parent instanceof STAC) {
        return this.parent;
      }
      return null;
    },
    andOrOptions() {
      return [
        { value: 'and', text: this.$t('search.logical.and') },
        { value: 'or', text: this.$t('search.logical.or') },
      ];
    },
    showAdditionalFilters() {
      return this.cql && Array.isArray(this.queryables) && this.queryables.length > 0;
    },
    sortOptions() {
      return [
        { value: null, text: this.$t('default') },
        { value: 'properties.datetime', text: this.$t('search.sortOptions.datetime') },
        { value: 'id', text: this.$t('search.sortOptions.id') },
        { value: 'properties.title', text: this.$t('search.sortOptions.title') }
      ];
    },
    sortedQueryables() {
      if (!Array.isArray(this.queryables)) {
        return [];
      }
      const collator = new Intl.Collator(this.uiLanguage);
      return this.queryables.slice(0).sort((a, b) => collator.compare(a.title, b.title));
    },
    maxItems() {
      return this.maxItemsPerPage || 1000;
    },
    datetime: {
      get() {
        return Array.isArray(this.query.datetime) ? this.query.datetime.map(d => Utils.dateFromUTC(d)) : null;
      },
      set(val) {
        this.query.datetime = Array.isArray(val) ? val.map(d => Utils.dateToUTC(d)) : null;
      }
    },
    naturalLanguageDescription() {
      return this.naturalLanguageExplanation;
    },
    spatialExtentOptions() {
      const options = [
        { value: 'none', text: this.$t('search.spatialExtentOptions.none') },
        { value: 'boundingBox', text: this.$t('search.spatialExtentOptions.boundingBox') },
      ];
      
      // Add natural search area option if available
      if (this.naturalSearchArea) {
        options.push({ 
          value: 'naturalSearchArea', 
          text: this.$t('search.spatialExtentOptions.naturalSearchArea') 
        });
      }
      
      return options;
    }
  },
  watch: {
    parent: {
      immediate: true,
      handler(newStac, oldStac) {
        if (newStac instanceof STAC) {
          newStac.setApiDataListener('searchfilter' + formId, () => this.updateApiCollections());
        }
        if (oldStac instanceof STAC) {
          oldStac.setApiDataListener('searchfilter' + formId);
        }
        this.updateApiCollections();
      }
    },
    value: {
      immediate: true,
      deep: true,
      handler(value) {
        this.query = Object.assign(getQueryDefaults(), value);
        if (this.collections.length > 0 && this.hasAllCollections) {
          this.selectedCollections = this.collections.filter(c => this.query.collections.includes(c.value));
        }
        else {
          this.selectedCollections = this.query.collections.map(id => {
            let collection = this.selectedCollections.find(c => c.value === id);
            return collection ? collection : this.collectionToMultiSelect({id});
          });
        }
      }
    }
  },
  beforeCreate() {
    formId++;
  },
  created() {
    let promises = [];
    if (this.cql && this.stac && this.type !== 'Collections') {
      let queryableLink = this.findQueryableLink(this.stac.links);
      promises.push(
        this.loadQueryables(queryableLink)
          .catch(error => console.error(error))
      );
    }
    if ((this.type === 'Collections' || this.conformances.CollectionIdFilter) && this.stac) {
      promises.push(
        this.loadCollections(this.stac.getApiCollectionsLink())
          .then(({collections, queryableLink}) => {
            this.collections = collections;
            if (this.collections.length > 0) {
              this.hasAllCollections = true;
            }
            return this.loadQueryables(queryableLink);
          })
          .catch(error => console.error(error))
      );
    }
    Promise.all(promises).finally(() => this.loaded = true);
  },
  methods: {
    async applyNaturalLanguageQuery(event) {
      // Prevent form submission
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }
      
      if (this.naturalLanguageQuery) {
        this.naturalLanguageLoading = true;
        this.naturalLanguageAction = 'populate';
        try {
          const SEMANTIC_SEARCH_API_URL = this.$store.state.semanticSearchApiUrl;
          const response = await fetch(`${SEMANTIC_SEARCH_API_URL}/items/search`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              return_search_params_only: true,
              query: this.naturalLanguageQuery,
              limit: 10
            })
          });

          if (!response.ok) {
            throw new Error(`API request failed with status ${response.status}`);
          }

          const responseData = await response.json();
          
          // Store the explanation if available in the response
          if (responseData.explanation) {
            this.naturalLanguageExplanation = responseData.explanation;
          } else if (responseData.results && responseData.results.explanation) {
            this.naturalLanguageExplanation = responseData.results.explanation;
          }
          
          // Extract datetime from search_params if available
          if (responseData.results && responseData.results.search_params && responseData.results.search_params.datetime) {
            const datetimeString = responseData.results.search_params.datetime;
            // Parse datetime string in format '2021-01-01/2022-12-31'
            const dates = datetimeString.split('/');
            if (dates.length === 2) {
              const startDate = dates[0] === '..' ? null : new Date(dates[0]);
              const endDate = dates[1] === '..' ? null : new Date(dates[1]);
              
              // Set the datetime in the query
              this.query.datetime = [startDate, endDate];
            }
          }
          
          // Extract collections from search_params if available
          if (responseData.results && responseData.results.search_params && responseData.results.search_params.collections) {
            const collectionIds = responseData.results.search_params.collections;
            if (Array.isArray(collectionIds) && collectionIds.length > 0) {
              // Remove duplicates and set collections in the query
              const uniqueCollectionIds = [...new Set(collectionIds)];
              this.$set(this.query, 'collections', uniqueCollectionIds);
              
              // Update selectedCollections to match the query collections
              this.selectedCollections = uniqueCollectionIds.map(id => {
                // Try to find existing collection in the collections array
                let existingCollection = this.collections.find(c => c.value === id);
                if (existingCollection) {
                  return existingCollection;
                }
                // If not found, create a new collection option
                return this.collectionToMultiSelect({id});
              });
            }
          }
          
          // Extract max_items from search_params if available
          if (responseData.results && responseData.results.search_params && responseData.results.search_params.max_items) {
            const maxItems = parseInt(responseData.results.search_params.max_items, 10);
            if (!isNaN(maxItems) && maxItems > 0) {
              // Ensure the value doesn't exceed the maximum allowed
              const limitedMaxItems = Math.min(maxItems, this.maxItems);
              this.$set(this.query, 'limit', limitedMaxItems);
            }
          }
          
          // Extract natural search area from search_params if available
          if (responseData.results && responseData.results.search_params && responseData.results.search_params.intersects) {
            const intersects = responseData.results.search_params.intersects;
            if (intersects) {
              this.naturalSearchArea = intersects;
              // Set spatial extent type to natural search area if available
              this.spatialExtentType = 'naturalSearchArea';
            }
          }
                    
          this.naturalLanguageError = null;
          
        } catch (error) {
          console.error('Error in semantic search:', error);
          this.naturalLanguageError = error.message;
        } finally {
          this.naturalLanguageLoading = false;
          this.naturalLanguageAction = null;
        }
      }
    },
    async directNaturalLanguageSearch(event) {
      // Prevent form submission
      if (event) {
        event.preventDefault();
        event.stopPropagation();
      }

      if (this.naturalLanguageQuery) {
        this.naturalLanguageLoading = true;
        this.naturalLanguageAction = 'search';
        try {
          const SEMANTIC_SEARCH_API_URL = this.$store.state.semanticSearchApiUrl;
          const response = await fetch(`${SEMANTIC_SEARCH_API_URL}/items/search`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              return_search_params_only: true,
              query: this.naturalLanguageQuery,
              limit: this.query.limit || this.itemsPerPage
            })
          });

          if (!response.ok) {
            throw new Error(`API request failed with status ${response.status}`);
          }

          const responseData = await response.json();

          // Create a search query from the response and emit it directly
          const searchQuery = {};

          if (responseData.results && responseData.results.search_params) {
            const params = responseData.results.search_params;
            
            // Extract datetime
            if (params.datetime) {
              const datetimeString = params.datetime;
              const dates = datetimeString.split('/');
              if (dates.length === 2) {
                const startDate = dates[0] === '..' ? null : new Date(dates[0]);
                const endDate = dates[1] === '..' ? null : new Date(dates[1]);
                searchQuery.datetime = [startDate, endDate];
              }
            }
            
            // Extract collections
            if (params.collections && Array.isArray(params.collections)) {
              searchQuery.collections = [...new Set(params.collections)];
            }
            
            // Extract limit
            if (params.max_items) {
              const maxItems = parseInt(params.max_items, 10);
              if (!isNaN(maxItems) && maxItems > 0) {
                searchQuery.limit = Math.min(maxItems, this.maxItems);
              }
            }
            
            // Extract spatial parameters
            if (params.intersects) {
              searchQuery.intersects = params.intersects;
              // Also store the natural search area locally for UI display
              this.naturalSearchArea = params.intersects;
              this.spatialExtentType = 'naturalSearchArea';
            }
          }

          // Store explanation for display
          if (responseData.explanation) {
            this.naturalLanguageExplanation = responseData.explanation;
          } else if (responseData.results && responseData.results.explanation) {
            this.naturalLanguageExplanation = responseData.results.explanation;
          }

          // Emit the search query directly to trigger immediate search
          this.$emit('input', searchQuery, false);

          this.naturalLanguageError = null;
          
        } catch (error) {
          console.error('Error in direct semantic search:', error);
          this.naturalLanguageError = error.message;
        } finally {
          this.naturalLanguageLoading = false;
          this.naturalLanguageAction = null;
        }
      }
    },
    resetSearchCollection() {
      clearTimeout(this.collectionsLoadingTimer);
      this.collectionsLoadingTimer = null;
    },
    searchCollections(text) {
      if (!this.canSearchCollectionsFreeText || this.hasAllCollections) {
        return;
      }
      this.resetSearchCollection();
      this.additionalCollectionCount = 0;
      if (typeof text !== 'string' || text.trim().length < 2) {
        this.collections = [];
        return;
      }
      this.collectionsLoadingTimer = setTimeout(async () => {
        try {
          const link = Utils.addFiltersToLink(this.collectionSearchLink, {q: [text]});
          const response = await stacRequest(this.$store, link);
          // Only set collections if response is valid AND collectionsLoadingTimer has not been reset.
          // If collectionsLoadingTimer has been reset, the result is not relevant anylonger.
          if (this.collectionsLoadingTimer && Utils.isObject(response.data) && Array.isArray(response.data.collections)) {
            this.collections = this.prepareCollections(response.data.collections);
            if (typeof response.data.numberMatched === 'number') {
              this.additionalCollectionCount = response.data.numberMatched - this.collections.length;
            }
          }
        } catch (error) {
          console.error(error);
          this.collections = [];
        } finally {
          this.resetSearchCollection();
        }
      }, 250);
    },
    async loadCollections(link) {
      let hasMore = false;
      let data = {
        collections: [],
        queryableLink: null
      };

      if (this.type === 'Global' && this.collections) {
        data.collections = this.collections;
        hasMore = false;
      }
      else if (this.type === 'Global' || this.type === 'Collections') {
        let response = await stacRequest(this.$store, link);
        if (!Utils.isObject(response.data)) {
          return {};
        }

        if (Array.isArray(response.data.links)) {
          let links = response.data.links;
          hasMore = Boolean(Utils.getLinkWithRel(links, 'next'));
          data.queryableLink = this.findQueryableLink(links) || null;
        }

        if (!hasMore && Array.isArray(response.data.collections)) {
          let collections = response.data.collections
            .map(collection => new STAC(collection));
          data.collections = this.prepareCollections(collections);
        }
      }
      return data;
    },
    updateApiCollections() {
      if (!this.parent) {
        return;
      }
      let apiCollections = this.parent.getChildren('collections');
      let nextCollectionsLink = this.parent._apiChildren.next;
      if (!Array.isArray(apiCollections) || nextCollectionsLink || !this.conformances.CollectionIdFilter) {
        this.collections = [];
        return;
      }
      this.collections = this.prepareCollections(apiCollections);
      if (this.collections.length > 0) {
        this.hasAllCollections = true;
      }
    },
    collectionToMultiSelect(c) {
      return {
        value: c.id,
        text: c.title || c.id
      };
    },
    prepareCollections(collections) {
      const collator = new Intl.Collator(this.uiLanguage);
      return collections
        .map(this.collectionToMultiSelect)
        .sort((a,b) => collator.compare(a.text, b.text));
    },
    findQueryableLink(links) {
      return Utils.getLinksWithRels(links, ogcQueryables)
          .find(link => Utils.isMediaType(link.type, schemaMediaType, true));
    },
    async loadQueryables(link) {
      this.queryables = [];

      if (!Utils.isObject(link)) {
        return;
      }

      let response = await stacRequest(this.$store, link);
      if (!Utils.isObject(response.data)) {
        return;
      }

      let schemas;
      try {
        schemas = await refParser.dereference(response.data);
      } catch (error) {
        // Use data with $refs included as fallback anyway
        console.error(error);
        schemas = response.data;
      }

      if (Utils.isObject(schemas) && Utils.isObject(schemas.properties)) {
        this.queryables = Object.entries(schemas.properties)
          .map(([key, schema]) => new Queryable(key, schema));
      }
    },
    sortFieldSet(value) {
      this.sortTerm = value;
    },
    sortDirectionSet(value) {
      this.sortOrder = value;
    },
    buildFilter() {
      if (this.filters.length === 0) {
        return null;
      }
      const args = this.filters.map(f => new f.operator(f.queryable, f.value));
      const logical = CqlLogicalOperator.create(this.filtersAndOr, args);
      return new Cql(logical);
    },
    removeQueryable(queryableIndex) {
      this.filters.splice(queryableIndex, 1);
    },
    additionalFieldSelected(queryable) {
      const operators = queryable.getOperators(this.cql);
      this.filters.push({
        value: CqlValue.create(queryable.defaultValue),
        operator: operators[0],
        queryable
      });
    },
    onSubmit() {
      if (this.canSort && this.sortTerm && this.sortOrder) {
        this.$set(this.query, 'sortby', this.formatSort());
      }
      let filters = this.buildFilter();
      this.$set(this.query, 'filters', filters);
      
      // Set spatial parameters based on current selection
      if (this.spatialExtentType === 'naturalSearchArea' && this.naturalSearchArea) {
        this.$set(this.query, 'intersects', this.naturalSearchArea);
        this.$set(this.query, 'bbox', null);
      } else if (this.spatialExtentType === 'boundingBox') {
        this.$set(this.query, 'bbox', this.query.bbox);
        this.$set(this.query, 'intersects', null);
      } else {
        // None selected
        this.$set(this.query, 'bbox', null);
        this.$set(this.query, 'intersects', null);
      }
      
      // Remove naturalLanguageQuery from the submitted query
      const submitQuery = { ...this.query };
      delete submitQuery.naturalLanguageQuery;
      
      // Only include intersects if it's not empty
      if (!submitQuery.intersects) {
        delete submitQuery.intersects;
      }
      
      this.$emit('input', submitQuery, false);
    },
    async onReset() {
      Object.assign(this, getDefaults());
      this.naturalLanguageQuery = '';
      this.naturalLanguageExplanation = '';
      this.naturalLanguageLoading = false;
      this.naturalLanguageError = null;
      this.naturalLanguageAction = null;
      this.naturalSearchArea = null;
      this.query.intersects = null;
      this.$emit('input', {}, true);
    },
    setLimit(limit) {
      limit = Number.parseInt(limit, 10);
      if (limit > this.maxItems) {
        limit = this.maxItems;
      }
      else if (typeof limit !== 'number' || isNaN(limit)|| limit < 1) {
        limit = null;
      }
      this.$set(this.query, 'limit', limit);
    },
    addSearchTerm(term) {
      if (!Utils.hasText(term)) {
        return;
      }
      this.query.q.push(term);
    },
    setSearchTerms(terms) {
      this.$set(this.query, 'q', terms);
    },
    setBBox(bounds) {
      let bbox = null;
      let intersects = null;
      
      if (this.spatialExtentType === 'boundingBox') {
        if (Utils.isObject(bounds) && typeof bounds.toBBoxString === 'function') {
          // This is a Leaflet LatLngBounds Object
          const Y = 85.06;
          const X = 180;
          bbox = [
            Math.max(bounds.getWest(), -X),
            Math.max(bounds.getSouth(), -Y),
            Math.min(bounds.getEast(), X),
            Math.min(bounds.getNorth(), Y)
          ];
        }
        else if (Array.isArray(bounds) && bounds.length === 4) {
          bbox = bounds;
        }
      }
      else if (this.spatialExtentType === 'naturalSearchArea' && this.naturalSearchArea) {
        // Use the natural search area as intersects parameter
        intersects = this.naturalSearchArea;
      }
      
      this.$set(this.query, 'bbox', bbox);
      this.$set(this.query, 'intersects', intersects);
    },
    addCollection(collection) {
      if (!this.collectionSelectOptions.taggable) {
        return;
      }
      this.resetSearchCollection();
      let opt = this.collectionToMultiSelect({id: collection});
      this.selectedCollections.push(opt);
      this.collections.push(opt);
      this.query.collections.push(collection);
    },
    setCollections(collections) {
      this.selectedCollections = collections;
      this.$set(this.query, 'collections', collections.map(c => c.value));
    },
    addId(id) {
      this.query.ids.push(id);
    },
    setIds(ids) {
      this.$set(this.query, 'ids', ids);
    },
    formatSort() {
      if (this.sortTerm && this.sortTerm.value && this.sortOrder) {
        let order = this.sortOrder < 0 ? '-' : '';
        return `${order}${this.sortTerm.value}`;
      }
      else {
        return null;
      }
    }
  }
};
</script>

